    vertices[vertexIndex]=GridVertex(vec4<f32>(position.x,0.0,position.y,1.0),vec4<f32>(0.0,1.0,0.0,0.0),vec4<f32>(1.0,0.0,0.0,-1.0),vec4<f32>(uv,0.0,0.0),vec4<f32>(1.0));
