  var primaryLength = centerLength;
  var primaryAnchor = pixel;
  var secondaryMotion = neighbourhoodSecondaryMotion;
  var secondaryLength = neighbourhoodSecondaryLength;
  var secondaryAnchor = neighbourhoodSecondaryAnchor;
