  let uncoveredColor = select(vec3<f32>(0.0), movingFallback, centerMoving);
  let acceptedAlpha = select(0.0, accum.a / max(weight, 1.0), weight > 0.0);
  let acceptedCoverage = weight + missingForeground * uncovered;
